            audits.add(new FB_Ticket_Audit__c(Ticket_Id__c = t.Id, Action__c = 'Escalated'));
        }

        // Use stripInaccessible to ensure FLS compliance for update
        List<FB_Ticket__c> accessibleTickets = (List<FB_Ticket__c>) Security.stripInaccessible(
            AccessType.UPDATABLE,
