        if (!accessibleTickets.isEmpty()) {
            update accessibleTickets;
        }

        // Insert audit records - use without sharing context to bypass sharing
        // CRUD is not enforced by default in Apex, so this works even though agents have no object access
        OrgWideHelper.insertAudits(audits);
    }

