public class ContactTriggerHandler {
    public static void handleContactTrigger(List<Contact> newContacts, Map<Id, Contact> newMap, Map<Id, Contact> oldMap, Boolean isBefore, Boolean isAfter, Boolean isInsert, Boolean isUpdate) {
        if (isBefore) {
            handleBeforeTrigger(newContacts, isInsert, isUpdate);
        }
        if (isAfter && isInsert) {
            handleAfterInsert(newContacts);
        }
    }

    private static void handleBeforeTrigger(List<Contact> contacts, Boolean isInsert, Boolean isUpdate) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        if (!accountIds.isEmpty()) {
            Map<Id, Account> accountsMap = new Map<Id, Account>([SELECT Id, BillingCountry, AccountSource FROM Account WHERE Id IN :accountIds]);

            for (Contact c : contacts) {
                if (c.AccountId != null && accountsMap.containsKey(c.AccountId)) {
                    Account a = accountsMap.get(c.AccountId);
                    if (String.isBlank(c.MailingCountry)) {
                        c.MailingCountry = a.BillingCountry;
                    }
                    if (isInsert && String.isBlank(c.LeadSource)) {
                        c.LeadSource = a.AccountSource;
                    }
                }
            }
        }
    }

    private static void handleAfterInsert(List<Contact> contacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIds.add(c.AccountId);
            }
        }

        if (!accountIds.isEmpty()) {
            Map<Id, Account> accountsMap = new Map<Id, Account>([SELECT Id, Phone FROM Account WHERE Id IN :accountIds]);
            List<Account> accountsToUpdate = new List<Account>();

            // Track which accounts have already been set in this trigger context
            Set<Id> processedAccounts = new Set<Id>();

            for (Contact c : contacts) {
                if (c.AccountId != null && String.isNotBlank(c.Phone) && accountsMap.containsKey(c.AccountId)) {
                    Account a = accountsMap.get(c.AccountId);
                    if (String.isBlank(a.Phone) && !processedAccounts.contains(c.AccountId)) {
                        a.Phone = c.Phone;
                        accountsToUpdate.add(a);
                        processedAccounts.add(c.AccountId); // Mark as processed to prevent overrides
                    }
                }
            }

            if (!accountsToUpdate.isEmpty()) {
                update accountsToUpdate;
            }
        }
    }
}
