@isTest
private class OpportunityWonHandlerTest {

    // -----------------------
    // Helper methods
    // -----------------------

    /**
     * Creates a minimal account with a non-Hot rating so the handler will update it.
     */
    private static Account createTestAccount(String rating) {
        Account acc = new Account(
            Name = 'Test Account ' + DateTime.now().getTime(),
            Rating = rating
        );
        insert acc;
        return acc;
    }

    /**
     * Builds an Opportunity record for insertion (no Id yet).
     */
    private static Opportunity buildOpportunity(Id accountId, String stageName) {
        return new Opportunity(
            Name = 'Test Opp',
            StageName = stageName,
            CloseDate = Date.today().addDays(10),
            AccountId = accountId
        );
    }

    /**
     * Inserts a single opportunity with the given stage and returns the saved record.
     */
    private static Opportunity insertOpportunity(Id accountId, String stageName) {
        Opportunity opp = buildOpportunity(accountId, stageName);
        insert opp;
        return opp;
    }

    /**
     * Retrieves the single task associated with the given opportunity (by WhatId).
     * Fails explicitly if zero or more than one task is found.
     */
    private static Task getTaskForOpportunity(Id oppId) {
        List<Task> tasks = [
            SELECT Subject, WhatId, OwnerId, ActivityDate, Priority
            FROM Task
            WHERE WhatId = :oppId
        ];
        System.assertEquals(1, tasks.size(), 'Expected exactly one task for opportunity ' + oppId);
        return tasks[0];
    }

