public class ErpAccountSyncJob implements Queueable {
    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpAccountSyncJob(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds;
        this.attempt = attempt;
    }

    public void execute(QueueableContext context) {
        System.attachFinalizer(new ErpSyncFinalizer(accountIds, attempt));

        List<Account> accounts = [
            SELECT Id, Description
            FROM Account
            WHERE Id IN :accountIds
        ];

        for (Account acc : accounts) {
            acc.Description = 'Synced to ERP';
        }

        Database.SaveResult[] results = Database.update(accounts, false);

        Boolean allOrNoneFailed = false;
        for (Database.SaveResult result : results) {
            if (!result.isSuccess()) {
                allOrNoneFailed = true;
                break;
            }
        }

        if (allOrNoneFailed) {
            Database.SaveResult[] forcedRollback = Database.update(accounts, true);
            // If execution reaches here, no exception was thrown, but since we set
            // allOrNone = true it will throw if any fail. We let it throw to fail the job.
        }
    }
}
