        ((fflib_ISObjectUnitOfWork) mocks.verify(mockUow, mocks.times(1))).registerDirty(staleOpp2);
        ((fflib_ISObjectUnitOfWork) mocks.verify(mockUow, mocks.never())).registerDirty(openOpp);
        ((fflib_ISObjectUnitOfWork) mocks.verify(mockUow, mocks.never())).registerDirty(wonOpp);

        // commitWork called once
        ((fflib_ISObjectUnitOfWork) mocks.verify(mockUow, mocks.times(1))).commitWork();
    }


