       }

       // Handle qualifying logic for After Update
       public override void onAfterUpdate(Map<Id, SObject> mapOld, Map<Id, SObject> mapNew) {
           List<Opportunity> qualifiedOpps = new List<Opportunity>();
           for (Id oppId : mapNew.keySet()) {
               Opportunity newOpp = (Opportunity)mapNew.get(oppId);
               Opportunity oldOpp = (Opportunity)mapOld.get(oppId);
               if (newOpp.StageName == 'Closed Won' && oldOpp.StageName != 'Closed Won') {
                   qualifiedOpps.add(newOpp);
               }
           }
           processQualifyingOpportunities(qualifiedOpps);
       }

       private void processQualifyingOpportunities(List<SObject> opps) {
           Set<Id> qualifyingIds = new Set<Id>();
           for (SObject so : opps) {
               Opportunity opp = (Opportunity)so;
               if (opp.StageName == 'Closed Won') {
                   qualifyingIds.add((Id)so.get('Id'));
               }
           }
           if (!qualifyingIds.isEmpty()) {
               IOpportunityFulfilmentService service =
                   (IOpportunityFulfilmentService) Application.Service.newInstance(IOpportunityFulfilmentService.class);
