        super(records);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> records) {
            return new Opportunities(records);
        }
    }

    public override void applyValidation() {
        super.applyValidation();

        List<Opportunity> recordsToValidate = (List<Opportunity>) getRecords();

        for (Opportunity opp : recordsToValidate) {
            // Rule 1: Amount must not be negative (insert and update)
            if (opp.Amount != null && opp.Amount < 0) {
                opp.Amount.addError('Amount cannot be negative.');
                error('Amount cannot be negative.', opp, Opportunity.Amount);
            }
        }

        // Rule 2: On update, a previously Closed Won opportunity cannot have its Amount changed.
        // Closing as Won and changing Amount in the same update is allowed.
        if (Trigger.isUpdate) {
            for (Opportunity opp : recordsToValidate) {
                Opportunity oldOpp = (Opportunity) Trigger.oldMap.get(opp.Id);
                Boolean wasClosedWon = oldOpp != null &&
                    oldOpp.StageName == 'Closed Won' &&
                    oldOpp.Amount == opp.Amount;

                if (wasClosedWon && opp.Amount != oldOpp.Amount) {
                    opp.Amount.addError('Amount cannot change on a won opportunity.');
                    error('Amount cannot change on a won opportunity.', opp, Opportunity.Amount);
                }
            }
        }

        if (getErrors().size() > 0) {
            fflib_SObjectDomain.Errors errors = new fflib_SObjectDomain.Errors(getErrors());
            errors.process();
        }
    }
}
