import { LightningElement, api } from 'lwc';

export default class CaseStatusBadge extends LightningElement {
    @api status;

    get hasStatus() {
        return this.status !== null && this.status !== undefined && this.status !== '';
    }

    get badgeClass() {
        const base = 'slds-badge';
        if (this.status === 'New') {
            return `${base} slds-theme_info`;
        } else if (this.status === 'Escalated') {
            return `${base} slds-theme_error`;
        } else if (this.status === 'Closed') {
            return `${base} slds-theme_success`;
        }
        return base;
    }
}
