        if (this.debounceTimeout) {
            clearTimeout(this.debounceTimeout);
            this.debounceTimeout = null;
        }
        // Mark current request as invalid by incrementing requestId
        this.requestId++;
    }

    handleChange(event) {
        const value = event.detail.value;
        this.searchTerm = value;

        // Clear any existing debounce timer
        if (this.debounceTimeout) {
            clearTimeout(this.debounceTimeout);
        }

        const trimmedValue = value.trim();

        // If fewer than 2 characters, cancel pending search and clear results
        if (trimmedValue.length < 2) {
            this.results = [];
            this.error = undefined;
            this.isLoading = false;
            return;
        }

        // Set up debounced search
        this.debounceTimeout = setTimeout(() => {
            this.performSearch(trimmedValue);
        }, 300);
    }

    async performSearch(searchTerm) {
        // Check if component is still active
        if (!this.isActive) {
            return;
        }

        // Increment requestId to mark any previous requests as stale
        const currentRequestId = ++this.requestId;
        this.pendingRequest = true;
        this.isLoading = true;
        this.error = undefined;

        try {
            // Call the Apex method
            const result = await searchContacts({ searchTerm });

            // Only update results if this is still the most recent request
            // and the component is still active
            if (this.requestId === currentRequestId && this.isActive) {
                this.results = result;
                this.pendingRequest = false;
            }
        } catch (error) {
            // Only update error if this is still the most recent request
            if (this.requestId === currentRequestId && this.isActive) {
                this.error = error;
                this.results = [];
                this.pendingRequest = false;
            }
        } finally {
            // Hide loading spinner if this was the most recent request
            if (this.requestId === currentRequestId && this.isActive) {
                this.isLoading = false;
            }
        }
    }
}
