```javascript
import { LightningElement, api, wire, track } from "lwc";
import { updateRecord } from "lightning/uiRecordApi";
import { ShowToastEvent } from "lightning/platformShowToastEvent";
import getContacts from "@salesforce/apex/ContactController.getContacts";
import { refreshApex } from "@salesforce/apex";

export default class AccountContactsTable extends LightningElement {
  @api recordId;

  @track draftValues = [];

  @wire(getContacts, { accountId: "$recordId" })
  contacts;

  columns = [
    {
      label: "Name",
      fieldName: "Name",
      type: "text",
      editable: false
    },
    {
      label: "Title",
      fieldName: "Title",
      type: "text",
      editable: true
    },
    {
      label: "Phone",
      fieldName: "Phone",
      type: "phone",
      editable: true
    },
    {
      label: "Email",
      fieldName: "Email",
      type: "email",
      editable: true
    }
  ];

  handleSave(event) {
    // Copy draft values so we can clear the datatable immediately
    const drafts = event.detail.draftValues;
    this.draftValues = [];

    // Build an array of save promises, each using updateRecord
    const savePromises = drafts.map((draft) => {
      const recordInput = {
        fields: { ...draft }
      };
      return updateRecord(recordInput);
    });

    // Run all save operations in parallel
    Promise.all(savePromises)
      .then(() => {
        // All updates succeeded -> show success toast
        this.dispatchEvent(
          new ShowToastEvent({
            title: "Contacts updated",
            variant: "success"
          })
        );

        // Clear draft values
        this.draftValues = [];

        // Refresh the wired data
        refreshApex(this.contacts);
      })
      .catch((error) => {
        // At least one update failed -> show error toast
        this.dispatchEvent(
          new ShowToastEvent({
            title: "Could not save contacts",
            message: error.body.message,
            variant: "error"
          })
        );

        // Restore draft values so user can retry
        this.draftValues = drafts;
      });
  }
}
