import { LightningElement, wire } from 'lwc';
import {
    subscribe,
    unsubscribe,
    publish,
    MessageContext,
    APPLICATION_SCOPE
} from 'lightning/messageService';
import accountSelected from '@salesforce/messageChannel/Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
    messageContext;
    subscription = null;
    recordId = null;

    @wire(MessageContext)
    setMessageContext(messageContext) {
        this.messageContext = messageContext;
        this.subscribeToMessageChannel();
    }

    connectedCallback() {
        this.subscribeToMessageChannel();
    }

    disconnectedCallback() {
        this.unsubscribeToMessageChannel();
    }

    subscribeToMessageChannel() {
        if (!this.subscription && this.messageContext) {
            this.subscription = subscribe(
                this.messageContext,
                accountSelected,
                (message) => this.handleMessageReceived(message),
                { scope: APPLICATION_SCOPE }
            );
        }
    }

    unsubscribeToMessageChannel() {
        if (this.subscription) {
            unsubscribe(this.subscription, (error) => {
                console.error('Failed to unsubscribe:', error);
            });
            this.subscription = null;
        }
    }

    handleMessageReceived(message) {
        this.recordId = message && message.recordId ? message.recordId : null;
    }

    handleClear() {
        publish(this.messageContext, accountSelected, { recordId: null });
    }
}
