import { LightningElement, track } from 'lwc';
import register from '@salesforce/apex/RegistrationController.register';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';

const PERSONAL_EMAIL_DOMAINS = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];

export default class EventRegistrationForm extends LightningElement {
    @track fullName = '';
    @track email = '';
    @track company = '';

    handleInputChange(event) {
        const field = event.target.dataset.field;
        this[field] = event.detail.value;
    }

    handleRegister() {
        const emailInput = this.template.querySelector('[data-field="email"]');
        const emailDomain = (this.email || '').split('@')[1] || '';

        if (PERSONAL_EMAIL_DOMAINS.includes(emailDomain.toLowerCase())) {
            emailInput.setCustomValidity('Use your work email address.');
        } else {
            emailInput.setCustomValidity('');
        }

        const allInputs = this.template.querySelectorAll('lightning-input');
        let isValid = true;

        allInputs.forEach(input => {
            if (!input.reportValidity()) {
                isValid = false;
            }
        });

        if (!isValid) {
            return;
        }

        register({
            fullName: this.fullName,
            email: this.email,
            company: this.company
        })
            .then(result => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        variant: 'success',
                        title: 'Registered'
                    })
                );
            })
            .catch(error => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        variant: 'error',
                        title: 'Registration failed',
                        message: error.body.message
                    })
                );
            });
    }
}
