import { LightningElement, api, track } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label;
    @api options = [];
    @api value;

    @track activeOptionId;

    connectedCallback() {
        this.updateActiveOptionId();
    }

    renderedCallback() {
        // not currently needed
    }

    get listboxClasses() {
        return ['slds-listbox', 'slds-listbox_vertical'].join(' ');
    }

    get activeOptionIndex() {
        const selectedIndex = this.options.findIndex(
            (option) => option.value === this.value
        );

        return selectedIndex >= 0 ? selectedIndex : 0;
    }

    get activeOption() {
        const activeIndex = this.activeOptionIndex;

        return this.options[activeIndex];
    }

    get optionItems() {
        return this.options.map((option, index) => {
            const isSelected = option.value === this.value;
            const optionId = `statusListbox-option-${index}`;

            return {
                ...option,
                id: optionId,
                'data-value': option.value,
                selected: isSelected,
                index,
            };
        });
    }

    updateActiveOptionId() {
        this.activeOptionId = `statusListbox-option-${this.activeOptionIndex}`;

        // If there are no options, activeOptionId should be null
        if (this.options.length === 0) {
            this.activeOptionId = null;
        }
    }

    handleKeyDown(event) {
        const key = event.key;

        if (key === 'ArrowDown') {
            event.preventDefault();
            this.moveActiveOption(1);
        } else if (key === 'ArrowUp') {
            event.preventDefault();
            this.moveActiveOption(-1);
        } else if (key === 'Home') {
            event.preventDefault();
            this.setActiveOptionIndex(0);
        } else if (key === 'End') {
            event.preventDefault();
            this.setActiveOptionIndex(this.options.length - 1);
        } else if (key === 'Enter' || key === ' ') {
            event.preventDefault();
            this.selectActiveOption();
        }
        // All other keys (including Tab) keep their default behavior
    }

    moveActiveOption(delta) {
        const currentActiveIndex = this.options.findIndex(
            (option) => option.value === this.getValueForActiveOption()
        );

        let newIndex = currentActiveIndex + delta;

        // Clamp the index between 0 and options.length - 1
        newIndex = Math.max(0, Math.min(newIndex, this.options.length - 1));

        this.setActiveOptionIndex(newIndex);
    }

    getValueForActiveOption() {
        const activeOptionElement = this.template.querySelector(
            `[id="${this.activeOptionId}"]`
        );

        return activeOptionElement ? activeOptionElement.dataset.value : null;
    }

    setActiveOptionIndex(index) {
        this.activeOptionId = `statusListbox-option-${index}`;
    }

    selectActiveOption() {
        const activeElement = this.template.querySelector(
            `[id="${this.activeOptionId}"]`
        );

        if (!activeElement) {
            return;
        }

        const newValue = activeElement.dataset.value;

        if (newValue === this.value) {
            // Already selected, don't dispatch change
            return;
        }

        this.dispatchEvent(
            new CustomEvent('change', {
                detail: {
                    value: newValue,
                },
            })
        );
    }

    handleOptionClick(event) {
        const clickedOption = event.currentTarget;
