import { LightningElement, api, track } from 'lwc';

export default class TaskChecklist extends LightningElement {
    @api heading;
    @api get tasks() {
        return this._tasks;
    }
    set tasks(value) {
        this._tasks = Array.isArray(value) ? value.map((task) => ({ ...task })) : [];
        this.items = this._tasks.map((task) => ({ ...task }));
    }
    _tasks = [];

    @track items = [];
    @track newLabel = '';
    nextId = 1;

    connectedCallback() {
        // do not mutate the public heading value
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const trimmed = (this.newLabel || '').trim();
        if (!trimmed) {
            return;
        }
        const label = trimmed;
        const id = `new-${this.nextId++}`;
        this.items = [...this.items, { id, label, done: false }];
        this.newLabel = '';
        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label } }));
    }

    handleToggle(event) {
        const id = event.target.dataset.id;
        this.items = this.items.map((task) =>
            task.id === id ? { ...task, done: !task.done } : task
        );
    }
}
