public class GauAllocationService {
    public class AllocationException extends Exception {}

    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        savepoint sp = Database.setSavepoint();

        try {
            List<npsp__Allocation__c> existingAllocations = [
                SELECT Id
                FROM npsp__Allocation__c
                WHERE npsp__Opportunity__c = :opportunityId
            ];

            if (percentByGauId == null || percentByGauId.isEmpty()) {
                throw new AllocationException('Percent by GAU map cannot be null or empty.');
            }

            List<General_Accounting_Unit__c> gaus = [
                SELECT Id, npsp__Active__c
                FROM General_Accounting_Unit__c
                WHERE Id IN :percentByGauId.keySet()
            ];

            Decimal totalPercent = 0;
            for (General_Accounting_Unit__c gau : gaus) {
                Decimal percent = percentByGauId.get(gau.Id);

                if (percent == null || percent <= 0) {
                    throw new AllocationException('GAU percentage must be greater than 0.');
                }

                if (!gau.npsp__Active__c) {
                    throw new AllocationException('GAU ' + gau.Id + ' is not active.');
                }

                totalPercent += percent;
            }

            if (totalPercent > 100) {
                throw new AllocationException('Total GAU percentages exceed 100.');
            }

            if (!existingAllocations.isEmpty()) {
                delete existingAllocations;
            }

            List<npsp__Allocation__c> allocationsToInsert = new List<npsp__Allocation__c>();
            for (General_Accounting_Unit__c gau : gaus) {
                Decimal percent = percentByGauId.get(gau.Id);

                allocationsToInsert.add(new npsp__Allocation__c(
                    npsp__Opportunity__c = opportunityId,
                    npsp__General_Accounting_Unit__c = gau.Id,
                    npsp__Percent__c = percent,
                    npsp__Amount__c = null
                ));
            }

            insert allocationsToInsert;

            return allocationsToInsert;
        } catch (Exception e) {
            Database.rollback(sp);
            throw e;
        }
    }
}
