        Boolean wasClosedWonBig = (oldOpp != null)
            && (oldOpp.StageName == 'Closed Won')
            && (oldOpp.Amount != null && oldOpp.Amount >= 5000);

        Boolean isClosedWonBig = (newOpp.StageName == 'Closed Won')
            && (newOpp.Amount != null && newOpp.Amount >= 5000);

        return isClosedWonBig && !wasClosedWonBig;
    }
